def _encode(vals, left, right, root):
    if root == -1:
        return []
    out = []
    q = [root]
    for x in q:
        if x == -1:
            out.append(-1)
        else:
            out.append(vals[x])
            q.append(left[x])
            q.append(right[x])
    while out and out[-1] == -1:
        out.pop()
    return out


def deserializePreorder(data):
    vals, left, right = [], [], []
    stack = []  # [node id, next slot to fill: 0 = left, 1 = right]
    root = -1
    for x in data:
        child = -1
        if x != -1:
            child = len(vals)
            vals.append(x)
            left.append(-1)
            right.append(-1)
        if stack:
            top = stack[-1]
            if top[1] == 0:
                left[top[0]] = child
                top[1] = 1
            else:
                right[top[0]] = child
                stack.pop()
        else:
            root = child
        if child != -1:
            stack.append([child, 0])
    return _encode(vals, left, right, root)
